    vocabulary: [["Veto","(Noun) The power to reject a decision."],["Triage","(Noun) Prioritising care or action under scarcity."],["Rubber stamp","(Noun) Approval given automatically without real scrutiny."],["Interrogate","(Verb) To question closely and critically."],["Liability","(Noun) Legal or moral responsibility for harm."],["Disparate impact","(Noun) Unequal effects on different groups despite neutral rules."],["Validation","(Noun) Evidence that a method works as claimed."],["Throughput","(Noun) The amount processed in a given time."],["Dissent","(Noun) Disagreement with a prevailing decision or view."],["Defer","(Verb) To yield to another’s judgment."],["Interruptibility","(Noun) The capacity for a process to be stopped or challenged."],["Coercion","(Noun) Forcing someone to act through pressure or threats."],["Conscience","(Noun) An inner moral sense guiding action."],["Cosplay","(Noun) Costume play; here, imitation without substance."],["Irreversible","(Adjective) Impossible to undo."],["Governance","(Noun) The systems and rules by which decisions are steered."]],
