    vocabulary: [["Atrophy","(Noun) Decline of a capacity through lack of use."],["Wayfinding","(Noun) The ability to navigate through physical space."],["Drudgery","(Noun) Dull, repetitive hard work."],["Number sense","(Noun) Intuitive understanding of quantities and relations."],["Premature","(Adjective) Happening too soon."],["Triage","(Noun) Prioritising under scarcity."],["Redundancy","(Noun) Extra capacity kept as backup."],["Apprenticeship","(Noun) Learning through guided practical experience."],["Curriculum","(Noun) A planned course of learning."],["Ambiguity","(Noun) Uncertainty of meaning or outcome."],["Nostalgia","(Noun) Longing for the past."],["Intervention","(Noun) The act of stepping in to change a process."],["Facility","(Noun) Effortless skill in doing something."],["Spatial","(Adjective) Relating to space and position."],["Unaided","(Adjective) Done without tool assistance."],["Deceitful","(Adjective) Misleading or dishonest."]],
