    vocabulary: [["Stewardship","(Noun) Responsible care for something entrusted to one."],["Brittle","(Adjective) Rigid and easily broken under stress."],["Succession","(Noun) The process of one person following another in a role."],["Interoperable","(Adjective) Able to work together across systems."],["Modular","(Adjective) Built from replaceable separate parts."],["Demystification","(Noun) Making something easier to understand by removing mystery."],["Maintainers","(Noun) People who keep systems working over time."],["Disruptors","(Noun) People or firms that upend existing markets or habits."],["E-waste","(Noun) Discarded electronic equipment."],["Literacy","(Noun) Competence in reading and, by extension, in a domain."],["Opaque","(Adjective) Not transparent; hard to inspect."],["Escalation","(Noun) Passing a problem to higher-level support."],["Debug","(Verb) To find and fix errors in software."],["Sealed","(Adjective) Closed so that opening or modifying is discouraged."],["Curriculum","(Noun) A planned programme of study."],["Helplessness","(Noun) The feeling of being unable to act effectively."]],
